s1 = rf(M, ESP - 7245788)
pc = 7
elseif pc == 7 then
EAX = ru(M, band(EDX + 16) - 7245824)
do local r = band(band(EAX, EAX), 4294967295)
FZ = r == 0
end
if FZ then pc = 9 else pc = 8 end
elseif pc == 8 then
s2 = s0
s2 = s2 * rf(M, band(EAX + 8) - 7245824)
do local x, y = s2, rf(M, band(EAX + 20) - 7245824); local r = x + y; if r == 0 then r = ZADD(x, y) end; s2 = r end
wfd(band(EAX + 20) - 7245824, s2)
EAX = ru(M, band(EAX + 24) - 7245824)
s1 = s1 * rf(M, band(EAX + 8) - 7245824)
do local x, y = s1, rf(M, band(EAX + 20) - 7245824); local r = x + y; if r == 0 then r = ZADD(x, y) end; s1 = r end
wfd(band(EAX + 20) - 7245824, s1)
EAX = ru(M, band(EAX + 24) - 7245824)
ECX = ru(M, band(EAX + 24) - 7245824)
EDX = ru(M, band(ECX + 24) - 7245824)
EAX = ru(M, band(EDX + 24) - 7245824)
ECX = ru(M, band(EAX + 24) - 7245824)
EDX = ru(M, band(ECX + 24) - 7245824)
EAX = ru(M, band(EDX + 24) - 7245824)
s1 = rf(M, band(EAX + 8) - 7245824)
s1 = s1 * s0
do local x, y = s1, rf(M, band(EAX + 20) - 7245824); local r = x + y; if r == 0 then r = ZADD(x, y) end; s1 = r end
wfd(band(EAX + 20) - 7245824, s1)
EAX = ru(M, band(EAX + 24) - 7245824)
s1 = rf(M, band(EAX + 8) - 7245824)
s1 = s1 * s0
do local x, y = s1, rf(M, band(EAX + 20) - 7245824); local r = x + y; if r == 0 then r = ZADD(x, y) end; s1 = r end
wfd(band(EAX + 20) - 7245824, s1)
ESP = ESP + 48
ESP = ESP + 4
do return end
elseif pc == 9 then
pc = 10
elseif pc == 10 then
ESP = ESP + 48
ESP = ESP + 4
do return end
end
end
end

-- registers are per module: calls between modules go through the shared register file ctx.R
local R = ctx.R
local function LOAD() EAX, EBX, ECX, EDX, ESI, EDI, EBP, ESP, FT, FSW = R[1], R[2], R[3], R[4], R[5], R[6], R[7], R[8], R[9], R[10] end
local function SAVE() R[1], R[2], R[3], R[4], R[5], R[6], R[7], R[8], R[9], R[10] = EAX, EBX, ECX, EDX, ESI, EDI, EBP, ESP, FT, FSW end
for a, f in pairs(XF) do
	ctx.XF[a] = function() LOAD(); f(); SAVE() end
end
setmetatable(XF, {__index = function(t, a)
	local g = ctx.XF[a]
	if not g then error(string.format("NR2003 track: call to unknown %08x", a)) end
	local s = function() SAVE(); g(); LOAD() end
	t[a] = s
	return s
end})
end

